import java.awt.Color;
import java.util.ArrayList;
import java.util.List;

public class EventTest {
    static class StubView implements SimulationView {
        public void setColor(Class<?> c, Color color) {}
    }
    static class Recorder implements SimulationListener {
        List<String> log = new ArrayList<>();
        public void simulationReset(SimulationEvent e) {
            log.add("RESET step=" + e.getStep() + " field=" + (e.getField()!=null));
        }
        public void simulationStepCompleted(SimulationEvent e) {
            log.add("STEP step=" + e.getStep() + " day=" + e.getDay() + " hour=" + e.getHour()
                    + " weather=" + (e.getWeather()!=null) + " time=" + e.getTime());
        }
    }

    public static void main(String[] a) {
        Randomizer.reset();
        StubView view = new StubView();
        Populator populator = new Populator(view);
        SimulationEngine engine = new SimulationEngine(10, 10, populator);
        Recorder rec = new Recorder();
        engine.addListener(rec);

        engine.reset();
        for (int i = 0; i < 3; i++) engine.simulateOneStep();

        boolean ok = true;
        // First event must be the reset at step 0.
        ok &= rec.log.get(0).equals("RESET step=0 field=true");
        // Then 3 step events with correct step/day/hour derivation.
        for (int s = 1; s <= 3; s++) {
            int day = s/120 + 1, hour = (s/5)%24 + 1;
            String expected = "STEP step=" + s + " day=" + day + " hour=" + hour + " weather=true time=";
            ok &= rec.log.get(s).startsWith(expected);
        }
        ok &= rec.log.size() == 4; // 1 reset + 3 steps, no events fired before listener attached/after

        rec.log.forEach(System.out::println);
        System.out.println(ok ? "PASS: events fire correctly (reset once at step 0, one per step with right data)"
                              : "FAIL");
        if (!ok) System.exit(1);
    }
}
